<?php
function diarioRegisterOperations($app,$auth){
 $app->post('/diario/preferencias',function($q,$r){$i=$q->getAttribute('diario');$p=$q->getParsedBody()?:[];$data=['titulo'=>diarioText($p['titulo']??'',80,true),'nombres'=>[]];foreach(['pendiente','en_curso','pausada','concluida','cancelada'] as $key)$data['nombres'][$key]=diarioText($p['nombres'][$key]??'',40,true);$theme=$p['tema']??'noche';$accent=$p['acento']??'#238d80';if(!in_array($theme,['noche','petroleo','uva','grafito','claro'],true)||!is_string($accent)||!preg_match('/^#[a-f0-9]{6}$/i',$accent))throw new InvalidArgumentException('Tema o color invalido.');$data['tema']=$theme;$data['acento']=$accent;$data['colores']=[];foreach(['pendiente','en_curso','pausada','concluida','cancelada'] as $state){$color=$p['colores'][$state]??['pendiente'=>'#8297aa','en_curso'=>'#3d86be','pausada'=>'#bb954d','concluida'=>'#269b7c','cancelada'=>'#9b7e8f'][$state];if(!is_string($color)||!preg_match('/^#[a-f0-9]{6}$/i',$color))throw new InvalidArgumentException('Color de columna invalido.');$data['colores'][$state]=$color;}$background=$p['fondo']??'';if(!is_string($background)||strlen($background)>750000)throw new InvalidArgumentException('La imagen de fondo es demasiado grande.');if($background!==''){if(!preg_match('~^data:image/jpeg;base64,([A-Za-z0-9+/=]+)$~',$background,$match))throw new InvalidArgumentException('Fondo de imagen invalido.');$binary=base64_decode($match[1],true);$image=$binary!==false?@getimagesizefromstring($binary):false;if(!$image||$image[2]!==IMAGETYPE_JPEG||$image[0]>1920||$image[1]>1920)throw new InvalidArgumentException('Imagen de fondo no valida.');}$data['fondo']=$background;$env=$p['entorno']??[];if(!is_array($env))throw new InvalidArgumentException('Colores del entorno invalidos.');$data['entorno']=['activo'=>!empty($env['activo'])];foreach(['fondo'=>'#e9efff','fondoFin'=>'#d9f4f1','encabezado'=>'#2454ce','panel'=>'#ffffff'] as $key=>$default){$color=$env[$key]??$default;if(!is_string($color)||!preg_match('/^#[a-f0-9]{6}$/i',$color))throw new InvalidArgumentException('Color del entorno invalido.');$data['entorno'][$key]=$color;}$s=$this->db->prepare('INSERT INTO Rhu_DiarioPreferencia(Usuario,Datos) VALUES(?,?) ON DUPLICATE KEY UPDATE Datos=VALUES(Datos)');$s->execute([$i['user'],json_encode($data,JSON_UNESCAPED_UNICODE)]);return $r->withJson($data);})->add($auth);
 $app->post('/diario/tareas/{id:[0-9]+}/atenciones',function($q,$r,$args){$db=$this->db;$i=$q->getAttribute('diario');$p=$q->getParsedBody()?:[];$key=$p['Clave']??'';if(!is_string($key)||!preg_match('/^[a-f0-9-]{36}$/',$key))throw new InvalidArgumentException('Actualiza el formulario antes de registrar.');$db->beginTransaction();$t=diarioTask($db,$args['id'],$i,true);$s=$db->prepare('SELECT Id,Tarea,Usuario,Cliente,Canal,Resultado,Detalle FROM Rhu_DiarioAtencion WHERE Clave=?');$s->execute([$key]);$old=$s->fetch(PDO::FETCH_ASSOC);
  $client=diarioText($p['Cliente']??($t['Proyecto']??''),180,true);$detail=diarioText($p['Detalle']??'',5000,true);$channel=$p['Canal']??'';$result=$p['Resultado']??'';
  if(!in_array($channel,['whatsapp','telefono','remoto','presencial','correo','ticket'],true)||!in_array($result,['resuelto','seguimiento','escalado'],true))throw new InvalidArgumentException('Revisa canal y resultado.');
  if($old){if((int)$old['Tarea']!==(int)$t['Id']||$old['Usuario']!==$i['user']||$old['Cliente']!==$client||$old['Canal']!==$channel||$old['Resultado']!==$result||$old['Detalle']!==$detail)throw new InvalidArgumentException('La operación ya existe con otros datos.');$db->commit();return $r->withJson(['Id'=>(int)$old['Id'],'repetida'=>true]);}
  if($t['TipoTrabajo']!=='soporte'||in_array($t['Estado'],['concluida','cancelada'],true))throw new InvalidArgumentException('Registra la atención en una tarea de soporte abierta.');$s=$db->prepare('INSERT INTO Rhu_DiarioAtencion(Tarea,Usuario,Fecha,Cliente,Canal,Resultado,Detalle,Clave) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$t['Id'],$i['user'],diarioNow(),$client,$channel,$result,$detail,$key]);$id=(int)$db->lastInsertId();diarioEvent($db,$t['Id'],$i['user'],'atencion',$client.' · '.$channel.' · '.$result.': '.$detail);$db->commit();return $r->withJson(['Id'=>$id]);
 })->add($auth);
 $app->get('/diario/soporte/diario',function($q,$r){$i=$q->getAttribute('diario');$p=$q->getQueryParams();$from=diarioDate(($p['desde']??substr(diarioNow(),0,10)).' 00:00:00');$to=diarioDate(($p['hasta']??substr(diarioNow(),0,10)).' 23:59:59');if($to<$from)throw new InvalidArgumentException('Revisa las fechas.');$params=[$from,$to];$where='a.Fecha BETWEEN ? AND ?';if(!$i['admin']||($p['vista']??'')==='mia'){$where.=' AND a.Usuario=?';$params[]=$i['user'];}
  $sql="SELECT DATE(a.Fecha) Dia,a.Usuario,COALESCE(u.NombreUsuario,a.Usuario) Nombre,COUNT(*) Atenciones,COUNT(DISTINCT a.Tarea) Casos,COUNT(DISTINCT CASE WHEN a.Resultado='resuelto' THEN a.Tarea END) CasosResueltos,SUM(a.Resultado='resuelto') Soluciones,SUM(a.Resultado='seguimiento') Seguimientos,SUM(a.Resultado='escalado') Escalados,COUNT(DISTINCT a.Cliente) Clientes FROM Rhu_DiarioAtencion a LEFT JOIN Seg_Usuario u ON u.Usuario=a.Usuario WHERE $where GROUP BY DATE(a.Fecha),a.Usuario,u.NombreUsuario ORDER BY Dia DESC,Nombre";$s=$this->db->prepare($sql);$s->execute($params);return $r->withJson(['dias'=>$s->fetchAll(PDO::FETCH_ASSOC)]);
 })->add($auth);
}
